corrected_code:
const BeeQueue = require('bee-queue');
const watermarkQueue = new BeeQueue('pdf-watermarking', { isWorker: false });

router.get('/api/documents/watermark-jobs/:jobId', jwtCheck, async (req, res) => {
  const job = await watermarkQueue.getJob(req.params.jobId);
  if (!job) return res.status(404).json({ error: 'Job not found' });
  if (job.data.userId !== req.user.id) {
    return res.status(403).json({ error: 'Access denied to target document job' });
  }
  res.json({
    progressPercent: job.progress,
    sourceFileName: job.data.originalFileName,
    fileSizeBytes: job.data.sizeBytes
  });
});
